'use strict'

import resource from '../resource'
import { SPRITE_TEXT_COLOR_RED, SPRITE_TEXT_COLOR_WHITE, WORLD_MAPS_PER_LINE, WORLD_MAPS_PER_COLUMN, SPRITE_TEXT_WIDTH, SPRITE_TEXT_HEIGHT } from '../constant'
import textManager from '../service/text-manager'

const SPRITE_WIDTH = 16
const SPRITE_HEIGHT = 16

const MAP_WIDTH = 128
const MAP_HEIGTH = 64

class TopMenu {
  constructor (link) {
    this.link = link

    this.map = undefined
    this.mapLocationWidth = undefined
    this.mapLocationHeight = undefined
  }

  initializeMap (map) {
    this.map = map

    /* const offsetBounds = WorldManager.getOffsetBoundsFromCategory(map.type)
    this.mapLocationWidth = MAP_WIDTH / (offsetBounds.maxX - offsetBounds.minX + 1)
    this.mapLocationHeight = MAP_HEIGTH / (offsetBounds.maxY - offsetBounds.minY + 1) */
  }

  draw (context) {
    // Background
    context.fillStyle = 'black'
    context.fillRect(0, 0, 512, 96)

    // Map
    context.translate(16, 16)
    context.fillStyle = 'grey'
    context.fillRect(0, 0, MAP_WIDTH, MAP_HEIGTH)
    const mapWidth = 128 / WORLD_MAPS_PER_LINE
    const mapHeight = 64 / WORLD_MAPS_PER_COLUMN
    context.fillStyle = 'green'
    context.fillRect(this.link.map.column * mapWidth, this.link.map.line * mapHeight, mapWidth, mapHeight)
    context.translate(-16, -16)

    // Rupees
    resource.getSprite('menu_rupee').draw(context, 160, 16, SPRITE_WIDTH, SPRITE_HEIGHT)
    textManager.draw(context, 'x' + this.link.inventory.rupees, SPRITE_TEXT_COLOR_WHITE, 176, 16, SPRITE_TEXT_WIDTH * 4, SPRITE_TEXT_HEIGHT, 'left')

    // Keys
    resource.getSprite('menu_key').draw(context, 160, 48, SPRITE_WIDTH, SPRITE_HEIGHT)
    textManager.draw(context, 'x' + this.link.inventory.keys, SPRITE_TEXT_COLOR_WHITE, 176, 48, SPRITE_TEXT_WIDTH * 4, SPRITE_TEXT_HEIGHT, 'left')

    // Bombs
    resource.getSprite('menu_bomb').draw(context, 160, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    textManager.draw(context, 'x' + this.link.inventory.bombs, SPRITE_TEXT_COLOR_WHITE, 176, 64, SPRITE_TEXT_WIDTH * 4, SPRITE_TEXT_HEIGHT, 'left')

    // Item B
    resource.getSprite('menu_blue_line_corner_north_west').draw(context, 256, 16, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 256, 32, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 256, 48, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_south_west').draw(context, 256, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_horizontal').draw(context, 272, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_south_east').draw(context, 288, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 288, 48, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 288, 32, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_north_east').draw(context, 288, 16, SPRITE_WIDTH, SPRITE_HEIGHT)
    textManager.draw(context, 'b', SPRITE_TEXT_COLOR_WHITE, 272, 16, 16, 16)
    if (this.link.itemB !== undefined) {
      this.link.itemB.draw(context, 256 + 8, 16 + 16)
    }

    // Item A
    resource.getSprite('menu_blue_line_corner_north_west').draw(context, 256 + 48, 16, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 256 + 48, 32, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 256 + 48, 48, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_south_west').draw(context, 256 + 48, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_horizontal').draw(context, 272 + 48, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_south_east').draw(context, 288 + 48, 64, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 288 + 48, 48, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_vertical').draw(context, 288 + 48, 32, SPRITE_WIDTH, SPRITE_HEIGHT)
    resource.getSprite('menu_blue_line_corner_north_east').draw(context, 288 + 48, 16, SPRITE_WIDTH, SPRITE_HEIGHT)
    textManager.draw(context, 'a', SPRITE_TEXT_COLOR_WHITE, 272 + 48, 16, 16, 16)
    if (this.link.itemA !== undefined) {
      this.link.itemA.draw(context, 256 + 48 + 8, 16 + 16)
    }

    // Life
    textManager.draw(context, '-life-', SPRITE_TEXT_COLOR_RED, 384, 16, 96, 16)
    let x = 368
    let y = 64
    for (let i = 0; i < this.link.totalLife; i++) {
      if (i < Math.floor(this.link.currentLife + 0.25)) {
        resource.getSprite('menu_heart_full').draw(context, x, y, SPRITE_WIDTH, SPRITE_HEIGHT)
      } else if (i < this.link.currentLife) {
        resource.getSprite('menu_heart_half').draw(context, x, y, SPRITE_WIDTH, SPRITE_HEIGHT)
      } else {
        resource.getSprite('menu_heart_empty').draw(context, x, y, SPRITE_WIDTH, SPRITE_HEIGHT)
      }

      x += SPRITE_WIDTH
      if (i === 7) {
        y -= SPRITE_HEIGHT
        x = 368
      }
    }
  }
}

export { TopMenu }
